import { Component } from '@angular/core';

interface Permission {
  id: number;
  name: string;
  description: string;
}

@Component({
  selector: 'app-permission-system',
  template: `
    <h2>Permission System</h2>

    <h3>Create New Permission</h3>
    <form>
      <input [(ngModel)]="newPermission.name" placeholder="Permission name" />
      <input [(ngModel)]="newPermission.description" placeholder="Description" />
      <!-- Add submit button here -->
    </form>

    <h3>Existing Permissions</h3>
    <ul>
      <li *ngFor="let permission of permissions">
        {{ permission.name }}: {{ permission.description }}
        <!-- Add delete button here -->
      </li>
    </ul>
  `
})
export class PermissionSystemComponent {
  permissions = [
    { id: 1, name: 'read', description: 'Can view content' },
    { id: 2, name: 'write', description: 'Can create content' },
    { id: 3, name: 'delete', description: 'Can remove content' }
  ];

  newPermission = { id: 0, name: '', description: '' };

  addPermission() {
    if (this.newPermission.name.trim()) {
      this.newPermission.id = this.permissions.length + 1;
      this.permissions.push({ ...this.newPermission });
      this.newPermission = { id: 0, name: '', description: '' };
    }
  }

  removePermission(id: number) {
    this.permissions = this.permissions.filter(p => p.id !== id);
  }
}
